const BASE_URL = 'http://localhost:8000/books';

export async function listBooks() {
  const res = await fetch(BASE_URL);
  if (!res.ok) throw new Error(`listBooks failed: ${res.status}`);
  return res.json();
}

export async function createBook(book) {
  const res = await fetch(BASE_URL, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(book),
  });
  if (!res.ok) throw new Error(`createBook failed: ${res.status}`);
  return res.json();
}

export async function updateBookStatus(id, status) {
  const res = await fetch(`${BASE_URL}/${id}`, {
    method: 'PATCH',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ status }),
  });
  if (!res.ok) throw new Error(`updateBookStatus failed: ${res.status}`);
  return res.json();
}

import { useEffect, useState } from 'react';
import { listBooks } from '../api';

export default function BookList() {
  const [books, setBooks] = useState([]);
  const [error, setError] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    listBooks()
      .then(setBooks)
      .catch((err) => setError(err.message))
      .finally(() => setLoading(false));
  }, []);

  if (loading) return <p>Caricamento libri...</p>;
  if (error) return <p>Errore: {error}</p>;
  if (books.length === 0) return <p>Nessun libro presente.</p>;

  return (
    <ul>
      {books.map((book) => (
        <li key={book.id}>
          <strong>{book.title}</strong> — {book.author}{' '}
          <em>({book.status})</em>
        </li>
      ))}
    </ul>
  );
}

import { useState } from 'react';
import { createBook } from '../api';

export default function BookForm({ onCreated }) {
  const [title, setTitle] = useState('');
  const [author, setAuthor] = useState('');
  const [status, setStatus] = useState('to_read');
  const [error, setError] = useState(null);

  async function handleSubmit(e) {
    e.preventDefault();
    setError(null);
    try {
      const book = await createBook({ title, author, status });
      setTitle('');
      setAuthor('');
      setStatus('to_read');
      if (onCreated) onCreated(book);
    } catch (err) {
      setError(err.message);
    }
  }

  return (
    <form onSubmit={handleSubmit}>
      <div>
        <label htmlFor="title">Titolo</label>
        <input
          id="title"
          type="text"
          value={title}
          onChange={(e) => setTitle(e.target.value)}
          required
        />
      </div>
      <div>
        <label htmlFor="author">Autore</label>
        <input
          id="author"
          type="text"
          value={author}
          onChange={(e) => setAuthor(e.target.value)}
          required
        />
      </div>
      <div>
        <label htmlFor="status">Stato</label>
        <select
          id="status"
          value={status}
          onChange={(e) => setStatus(e.target.value)}
        >
          <option value="to_read">Da leggere</option>
          <option value="reading">In lettura</option>
          <option value="read">Letto</option>
        </select>
      </div>
      {error && <p style={{ color: 'red' }}>{error}</p>}
      <button type="submit">Aggiungi libro</button>
    </form>
  );
}

import { useState } from 'react';
import BookList from './components/BookList';
import BookForm from './components/BookForm';

function App() {
  const [refreshKey, setRefreshKey] = useState(0);

  function handleBookCreated() {
    setRefreshKey((k) => k + 1);
  }

  return (
    <main>
      <h1>BookTrack</h1>

      <section>
        <h2>Aggiungi un libro</h2>
        <BookForm onCreated={handleBookCreated} />
      </section>

      <section>
        <h2>I miei libri</h2>
        <BookList key={refreshKey} />
      </section>
    </main>
  );
}

export default App;

